import {openPdf,renderPage,renderer} from '../tools/engine.js';
const $=selector=>document.querySelector(selector);
const F=fabric;
F.FabricObject.customProperties=['data'];
const canvas=new F.Canvas('document-canvas',{preserveObjectStacking:true,selection:true,enableRetinaScaling:true,backgroundColor:'#ffffff',stopContextMenu:true});
const state={pages:[],index:0,pdf:null,name:'Untitled document',zoom:1,mode:'select',busy:false,restoring:false,dirty:false,imageAction:'add',ocr:null,ocrCanceled:false};
const baseObject={originX:'left',originY:'top',cornerColor:'#ffffff',cornerStrokeColor:'#9b78bf',borderColor:'#b594d1',cornerStyle:'rect',transparentCorners:false,cornerSize:9,padding:3};
let toastTimer,propertyTimer;
const current=()=>state.pages[state.index];
const isText=object=>object instanceof F.IText||object instanceof F.Textbox||object instanceof F.FabricText;
const clamp=(number,min,max)=>Math.max(min,Math.min(max,number));
function notify(message,error=false){clearTimeout(toastTimer);$('#editor-toast').textContent=message;$('#editor-toast').classList.toggle('error',error);$('#editor-toast').hidden=false;toastTimer=setTimeout(()=>{$('#editor-toast').hidden=true;},error?7500:4500);}
function progress(title,detail='',value=0){state.busy=true;document.body.classList.add('editor-busy');$('#editor-progress').hidden=false;$('#progress-title').textContent=title;$('#progress-detail').textContent=detail||'Your files stay on this device.';$('#editor-progress-bar').value=value;}
function done(){state.busy=false;document.body.classList.remove('editor-busy');$('#editor-progress').hidden=true;$('#cancel-ocr').hidden=true;updateButtons();}
function makePage(width,height,source={type:'blank'}){return {id:crypto.randomUUID(),width,height,source,background:null,detected:[],prepared:false,scene:{objects:[]},history:[],position:-1};}
function configureObject(object,label='Element'){object.set({...baseObject,data:{...object.data,label}});object.setCoords();return object;}
function scene(){return {objects:canvas.getObjects().map(object=>object.toObject(['data']))};}
function saveScene(){if(current())current().scene=scene();}
function commit(){if(state.restoring||!current())return;clearTimeout(propertyTimer);const page=current();page.scene=scene();const serialized=JSON.stringify(page.scene);if(page.history[page.position]===serialized)return;page.history.splice(page.position+1);page.history.push(serialized);page.position=page.history.length-1;state.dirty=true;$('#save-status').textContent='Edits in this tab · export to save';updateButtons();renderLayers();renderHints();}
function updateButtons(){const active=!!current()&&!state.busy;document.querySelectorAll('.studio-toolbar button').forEach(button=>{button.disabled=!active&&button.id!=='open-file';});$('#export-editor').disabled=!active;$('#undo').disabled=!active||current().position<=0;$('#redo').disabled=!active||current().position>=current().history.length-1;$('#add-page').disabled=!active;}
async function backgroundImage(page){if(!page.background)return null;const image=await F.FabricImage.fromURL(page.background);image.set({originX:'left',originY:'top',left:0,top:0,scaleX:page.width/image.width,scaleY:page.height/image.height,selectable:false,evented:false});return image;}
async function preparePage(page){
  if(page.prepared)return;
  if(page.source.type==='pdf'){
    const result=await renderPage(state.pdf,page.source.index,2);page.background=result.canvas.toDataURL('image/png');const pdfPage=await state.pdf.getPage(page.source.index+1);const viewport=pdfPage.getViewport({scale:1});const lib=await renderer();const content=await pdfPage.getTextContent();
    for(const item of content.items){if(!item.str?.trim())continue;const tx=lib.Util.transform(viewport.transform,item.transform),angle=Math.atan2(tx[1],tx[0]);if(Math.abs(angle)>.03)continue;const size=Math.hypot(tx[2],tx[3]);if(!size)continue;const style=content.styles[item.fontName]||{};const ascent=style.ascent??(style.descent?1+style.descent:.82);const x=tx[4],y=tx[5]-size*ascent;const family=style.fontFamily||'sans-serif';page.detected.push({id:crypto.randomUUID(),text:item.str,x:clamp(x,0,page.width),y:clamp(y,0,page.height),width:Math.max(3,Math.abs(item.width)),height:size*1.16,fontSize:size,fontFamily:/monospace/i.test(family)?'Courier New':/sans/i.test(family)?'Arial':'Times New Roman',fontWeight:/bold/i.test(item.fontName)?'bold':'normal',fontStyle:'normal',origin:'PDF'});}
    result.canvas.width=result.canvas.height=0;
  }else if(page.source.type==='image'){
    page.background=page.source.data;
  }
  page.prepared=true;
}
async function loadScene(value,page=current()){
  state.restoring=true;
  try{await canvas.loadFromJSON(value);canvas.backgroundColor='#ffffff';canvas.backgroundImage=await backgroundImage(page);for(const object of canvas.getObjects())object.set({...baseObject});canvas.requestRenderAll();}
  finally{state.restoring=false;}
}
async function showPage(index,{save=true}={}){
  if(state.busy||index<0||index>=state.pages.length)return;
  clearTimeout(propertyTimer);if(save)saveScene();progress('Preparing your page…');state.index=index;const page=current();
  try{await preparePage(page);await loadScene(page.scene,page);$('#editor-empty').hidden=true;$('#editor-workspace').hidden=false;$('#canvas-page-label').textContent=`Page ${index+1} of ${state.pages.length}`;$('#page-dimensions').textContent=`${(page.width/72*25.4).toFixed(1)} × ${(page.height/72*25.4).toFixed(1)} mm`;renderPages();fitCanvas();setMode('select');updateSelection();if(!page.history.length){page.history=[JSON.stringify(page.scene)];page.position=0;}renderLayers();}
  catch(error){notify(error.message||'This page could not be rendered.',true);}
  finally{done();}
}
function renderPages(){$('#page-total').textContent=state.pages.length;$('#page-list').replaceChildren();state.pages.forEach((page,index)=>{const button=document.createElement('button');button.className='page-button'+(index===state.index?' active':'');button.setAttribute('aria-label',`Go to page ${index+1}`);const symbol=document.createElement('span');symbol.className='page-symbol';symbol.textContent=index+1;const text=document.createElement('span');text.textContent=`Page ${index+1}`;const small=document.createElement('small');small.textContent=page.width>page.height?'Landscape':'Portrait';button.append(symbol,text,small);button.onclick=()=>showPage(index);$('#page-list').append(button);});}
function setZoom(zoom){if(!current())return;state.zoom=clamp(zoom,.1,6);const page=current();canvas.setDimensions({width:Math.ceil(page.width*state.zoom),height:Math.ceil(page.height*state.zoom)});canvas.setViewportTransform([state.zoom,0,0,state.zoom,0,0]);canvas.requestRenderAll();$('#canvas-holder').style.width=Math.ceil(page.width*state.zoom)+'px';$('#canvas-holder').style.height=Math.ceil(page.height*state.zoom)+'px';$('#zoom-label').textContent=Math.round(state.zoom*100)+'%';renderHints();}
function fitCanvas(){if(!current())return;const scroll=$('#canvas-scroll');const availableWidth=scroll.clientWidth-(innerWidth<641?38:68),availableHeight=scroll.clientHeight-70;setZoom(Math.min(availableWidth/current().width,availableHeight/current().height,2.4));}
function setMode(mode){if(!current())return;state.mode=mode;canvas.isDrawingMode=mode==='draw';canvas.selection=mode==='select';canvas.skipTargetFind=mode==='existing';if(mode==='draw'){canvas.freeDrawingBrush=new F.PencilBrush(canvas);canvas.freeDrawingBrush.color=$('#fill-color').value||'#302d3d';canvas.freeDrawingBrush.width=2;}if(mode!=='select')canvas.discardActiveObject();document.querySelectorAll('[data-mode]').forEach(button=>{button.classList.toggle('active',button.dataset.mode===mode);button.setAttribute('aria-pressed',button.dataset.mode===mode);});$('#mode-hint').textContent=mode==='existing'?'Click a detected text area to replace its words.':mode==='draw'?'Draw on the page. Switch to Select to move or resize your drawing.':'Drag to move. Corner handles resize; the top handle rotates.';renderHints();canvas.requestRenderAll();}
function renderHints(){const container=$('#text-hints');container.replaceChildren();container.hidden=state.mode!=='existing'||!current();if(container.hidden)return;const used=new Set(canvas.getObjects().filter(object=>object.data?.role==='cover').map(object=>object.data.sourceId));for(const text of current().detected){if(used.has(text.id))continue;const button=document.createElement('button');button.className='text-hint';button.style.left=text.x*state.zoom+'px';button.style.top=text.y*state.zoom+'px';button.style.width=Math.min(text.width,current().width-text.x)*state.zoom+'px';button.style.height=text.height*state.zoom+'px';button.title='Edit: '+text.text;button.setAttribute('aria-label','Edit text: '+text.text);button.textContent=text.text;button.onclick=()=>replaceDetected(text);container.append(button);}if(!container.childElementCount)$('#mode-hint').textContent=current().detected.length?'All detected regions have been edited. Undo or restore an element to edit the original again.':'No editable text detected. Use Detect text in scan, or Cover area + Add text.';}
async function sampleBackground(box){const page=current();if(!page.background)return '#ffffff';try{const image=new Image();image.src=page.background;await image.decode();const sample=document.createElement('canvas');sample.width=image.naturalWidth;sample.height=image.naturalHeight;const ctx=sample.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);const sx=image.naturalWidth/page.width,sy=image.naturalHeight/page.height;const points=[[box.x-2,box.y-2],[box.x+box.width+2,box.y-2],[box.x-2,box.y+box.height+2],[box.x+box.width+2,box.y+box.height+2],[box.x+box.width/2,box.y-2],[box.x-2,box.y+box.height/2]];const colors=new Map();for(const [x,y]of points){const data=ctx.getImageData(clamp(Math.round(x*sx),0,image.naturalWidth-1),clamp(Math.round(y*sy),0,image.naturalHeight-1),1,1).data;const hex='#'+Array.from(data.slice(0,3),v=>v.toString(16).padStart(2,'0')).join('');colors.set(hex,(colors.get(hex)||0)+1);}sample.width=sample.height=0;return [...colors].sort((a,b)=>b[1]-a[1])[0][0];}catch{return '#ffffff';}}
async function replaceDetected(text){if(state.busy)return;const page=current();const generation=page.id;const coverColor=await sampleBackground(text);if(current()?.id!==generation)return;const cover=configureObject(new F.Rect({left:Math.max(0,text.x-1.2),top:Math.max(0,text.y-1),width:Math.min(text.width+2.4,page.width-text.x+1.2),height:Math.min(text.height+2,page.height-text.y+1),fill:coverColor,strokeWidth:0,selectable:false,evented:false,data:{role:'cover',sourceId:text.id}}),'Original text cover');const replacement=configureObject(new F.IText(text.text,{left:text.x,top:text.y,fontSize:text.fontSize,fontFamily:text.fontFamily||'Arial',fontWeight:text.fontWeight||'normal',fill:'#25212c',data:{role:'replacement',sourceId:text.id}}),'Replacement text');canvas.add(cover,replacement);setMode('select');canvas.setActiveObject(replacement);commit();updateSelection();if(innerWidth>640){replacement.enterEditing();replacement.selectAll();}canvas.requestRenderAll();notify('Edit the selected words or use Text content in the panel.');}
function colorValue(value,fallback='#302d3d'){try{const c=new F.Color(value||fallback);return '#'+c.toHex().slice(0,6);}catch{return fallback;}}
function updateSelection(){const object=canvas.getActiveObject();const multiple=object instanceof F.ActiveSelection;$('#no-selection').hidden=!!object&&!multiple;$('#object-properties').hidden=!object||multiple;if(!object||multiple){renderLayers();return;}const text=isText(object),image=object instanceof F.FabricImage;$('#selection-type').textContent=text?'Text element':image?'Image':object.data?.role==='cover-area'?'Cover area':'Shape / drawing';$('#text-properties').hidden=!text;$('#shape-properties').hidden=text||image;$('#image-properties').hidden=!image;$('#replacement-properties').hidden=object.data?.role!=='replacement';if(text){$('#text-value').value=object.text;$('#font-family').value=object.fontFamily;if(!$('#font-family').value){const option=document.createElement('option');option.value=object.fontFamily;option.textContent=object.fontFamily;$('#font-family').append(option);$('#font-family').value=object.fontFamily;}$('#font-size').value=Number(object.fontSize.toFixed(1));$('#fill-color').value=colorValue(object.fill);$('#text-align').value=object.textAlign||'left';$('#text-bold').setAttribute('aria-pressed',object.fontWeight==='bold'||Number(object.fontWeight)>=600);$('#text-italic').setAttribute('aria-pressed',object.fontStyle==='italic');$('#text-underline').setAttribute('aria-pressed',!!object.underline);}else{$('#shape-color').value=colorValue(object.fill,'#ffffff');$('#stroke-color').value=colorValue(object.stroke,'#7960d8');$('#stroke-width').value=object.strokeWidth||0;}if(object.data?.sourceId){const cover=canvas.getObjects().find(item=>item.data?.role==='cover'&&item.data.sourceId===object.data.sourceId);$('#cover-color').value=colorValue(cover?.fill,'#ffffff');}$('#object-x').value=Number(object.left.toFixed(1));$('#object-y').value=Number(object.top.toFixed(1));$('#object-width').value=Number(object.getScaledWidth().toFixed(1));$('#object-height').value=Number(object.getScaledHeight().toFixed(1));$('#object-angle').value=Number(object.angle.toFixed(1));$('#object-opacity').value=Math.round(object.opacity*100);renderLayers();}
function renderLayers(){const container=$('#layer-list');container.replaceChildren();const objects=canvas.getObjects().filter(object=>object.data?.role!=='cover').slice().reverse();for(const object of objects){const button=document.createElement('button');button.className='layer-button'+(canvas.getActiveObject()===object?' active':'');const type=document.createElement('span');type.textContent=isText(object)?'T':object instanceof F.FabricImage?'▧':object instanceof F.Path?'〰':'□';const label=document.createElement('span');label.textContent=isText(object)?object.text.replace(/\n/g,' '):object.data?.label||'Element';button.title=label.textContent;button.append(type,label);button.onclick=()=>{if(state.busy)return;setMode('select');canvas.setActiveObject(object);canvas.requestRenderAll();updateSelection();};container.append(button);}if(!objects.length){const empty=document.createElement('p');empty.className='property-note';empty.textContent='New and edited elements appear here.';container.append(empty);}}
function changeSelected(callback,{snapshot=true}={}){const object=canvas.getActiveObject();if(!object||object instanceof F.ActiveSelection||state.busy)return;if(object.isEditing)object.exitEditing();callback(object);object.setCoords();canvas.requestRenderAll();renderLayers();if(snapshot)commit();}
function propertyInput(id,callback){const input=$('#'+id);input.oninput=()=>{const value=input.value;changeSelected(object=>callback(object,value),{snapshot:false});input.value=value;clearTimeout(propertyTimer);propertyTimer=setTimeout(commit,450);};input.onchange=()=>{commit();updateSelection();};}
propertyInput('text-value',(object,value)=>{if(isText(object))object.set('text',value);});propertyInput('font-family',(object,value)=>object.set('fontFamily',value));propertyInput('font-size',(object,value)=>{const n=Number(value);if(n>0&&Number.isFinite(n))object.set('fontSize',n);});propertyInput('fill-color',(object,value)=>object.set('fill',value));propertyInput('text-align',(object,value)=>object.set('textAlign',value));propertyInput('shape-color',(object,value)=>object.set('fill',value));propertyInput('stroke-color',(object,value)=>object.set('stroke',value));propertyInput('stroke-width',(object,value)=>{const n=Number(value);if(n>=0&&Number.isFinite(n))object.set('strokeWidth',n);});propertyInput('cover-color',(object,value)=>{const cover=canvas.getObjects().find(item=>item.data?.role==='cover'&&item.data.sourceId===object.data?.sourceId);cover?.set('fill',value);});
for(const [id,key]of [['object-x','left'],['object-y','top'],['object-angle','angle']])propertyInput(id,(object,value)=>{const n=Number(value);if(Number.isFinite(n))object.set(key,n);});
propertyInput('object-width',(object,value)=>{const n=Number(value);if(n>0&&Number.isFinite(n))object.set('scaleX',n/(object.width+object.strokeWidth));});propertyInput('object-height',(object,value)=>{const n=Number(value);if(n>0&&Number.isFinite(n))object.set('scaleY',n/(object.height+object.strokeWidth));});propertyInput('object-opacity',(object,value)=>{const n=Number(value);if(Number.isFinite(n))object.set('opacity',clamp(n,0,100)/100);});
$('#text-bold').onclick=()=>{changeSelected(object=>object.set('fontWeight',object.fontWeight==='bold'?'normal':'bold'));updateSelection();};$('#text-italic').onclick=()=>{changeSelected(object=>object.set('fontStyle',object.fontStyle==='italic'?'normal':'italic'));updateSelection();};$('#text-underline').onclick=()=>{changeSelected(object=>object.set('underline',!object.underline));updateSelection();};
function addObject(object,label){if(!current()||state.busy)return;setMode('select');configureObject(object,label);canvas.add(object);canvas.setActiveObject(object);commit();updateSelection();canvas.requestRenderAll();}
function addText(){const page=current();if(!page)return;addObject(new F.IText('Your text here',{left:page.width*.12,top:page.height*.18,fontFamily:'Arial',fontSize:Math.min(22,page.width/17),fill:'#302d3d'}),'Text');}
function addRectangle(cover=false){const page=current();if(!page)return;addObject(new F.Rect({left:page.width*.12,top:page.height*.25,width:page.width*.35,height:page.height*.18,fill:cover?'#ffffff':'#e5d9f2',stroke:cover?null:'#ad8dc9',strokeWidth:cover?0:1,rx:cover?0:3,ry:cover?0:3,data:{role:cover?'cover-area':'shape'}}),cover?'Cover area':'Rectangle');if(cover)notify('Move and resize this cover, then add text or a photo above it.');}
function removeSelected(){if(state.busy)return;const objects=canvas.getActiveObjects();if(!objects.length)return;canvas.discardActiveObject();canvas.remove(...objects);commit();updateSelection();canvas.requestRenderAll();}
async function duplicateSelected(){const object=canvas.getActiveObject();if(!object||object instanceof F.ActiveSelection||state.busy)return;const cloned=await object.clone(['data']);cloned.set({left:object.left+12,top:object.top+12,data:{...cloned.data,role:cloned.data?.role==='replacement'?'text':cloned.data?.role,sourceId:undefined}});addObject(cloned,cloned.data?.label||'Copy');}
$('#delete-object').onclick=removeSelected;$('#duplicate-object').onclick=duplicateSelected;$('#bring-forward').onclick=()=>{const object=canvas.getActiveObject();if(!object||state.busy)return;canvas.bringObjectForward(object);commit();canvas.requestRenderAll();};$('#send-backward').onclick=()=>{const object=canvas.getActiveObject();if(!object||state.busy)return;const index=canvas.getObjects().indexOf(object),behind=canvas.getObjects()[index-1];if(behind?.data?.role==='cover'){notify('Replacement text stays above the cover hiding its original.');return;}canvas.sendObjectBackwards(object);commit();canvas.requestRenderAll();};
$('#restore-original').onclick=()=>{const object=canvas.getActiveObject();if(!object?.data?.sourceId)return;const id=object.data.sourceId;canvas.discardActiveObject();canvas.remove(...canvas.getObjects().filter(item=>item.data?.sourceId===id));commit();updateSelection();setMode('existing');notify('Original text restored.');};
async function undoRedo(direction){if(state.busy||!current())return;clearTimeout(propertyTimer);const page=current(),target=page.position+direction;if(target<0||target>=page.history.length)return;progress(direction<0?'Undoing your last edit…':'Restoring your next edit…');try{page.position=target;page.scene=JSON.parse(page.history[target]);await loadScene(page.scene);updateSelection();renderHints();}catch(error){notify(error.message,true);}finally{done();}}
$('#undo').onclick=()=>undoRedo(-1);$('#redo').onclick=()=>undoRedo(1);
canvas.on('selection:created',updateSelection);canvas.on('selection:updated',updateSelection);canvas.on('selection:cleared',updateSelection);canvas.on('object:modified',()=>{commit();updateSelection();});canvas.on('text:editing:exited',()=>{commit();updateSelection();});canvas.on('text:changed',()=>{const object=canvas.getActiveObject();if(object&&isText(object))$('#text-value').value=object.text;});canvas.on('path:created',({path})=>{configureObject(path,'Freehand drawing');commit();});
function resetDocument(){clearTimeout(propertyTimer);state.pdf?.destroy().catch(()=>{});state.pdf=null;state.pages=[];state.index=0;state.dirty=false;canvas.discardActiveObject();canvas.clear();$('#document-name').value=state.name;}
async function openFile(file){
  if(!file||state.busy)return;if(!/\.(pdf|png|jpe?g|webp)$/i.test(file.name)){notify('Choose a PDF, JPG, PNG, or WebP file.',true);return;}
  if(state.dirty&&!confirm('Open a new document? Export first if you want to keep the current edits.'))return;
  progress('Opening your document…');
  try{let pages,pdf=null;const name=file.name.replace(/\.[^.]+$/,'');if(/\.pdf$/i.test(file.name)){pdf=await openPdf(file);pages=[];for(let index=0;index<pdf.numPages;index++){const page=await pdf.getPage(index+1),view=page.getViewport({scale:1});pages.push(makePage(view.width,view.height,{type:'pdf',index}));}}else{const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const source=document.createElement('canvas');source.width=image.naturalWidth;source.height=image.naturalHeight;const ctx=source.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,source.width,source.height);ctx.drawImage(image,0,0);pages=[makePage(image.naturalWidth*.75,image.naturalHeight*.75,{type:'image',data:source.toDataURL('image/png')})];source.width=source.height=0;}finally{URL.revokeObjectURL(url);}}
    resetDocument();state.name=name;state.pdf=pdf;state.pages=pages;$('#document-name').value=name;done();await showPage(0,{save:false});notify('Your document is ready. Use Edit existing text, or add your own elements.');
  }catch(error){notify(error.name==='PasswordException'?'This PDF needs a password. Use Unlock PDF in the toolkit first.':error.message||'This document could not be opened.',true);done();}
}
function presetSize(preset){return preset==='card'?[85.6/25.4*72,54/25.4*72]:preset==='same'&&current()?[current().width,current().height]:[595.28,841.89];}
async function blankDocument(preset,sample=false){if(state.busy)return;if(state.dirty&&!confirm('Start a new document? Export first if you want to keep the current edits.'))return;resetDocument();const [width,height]=presetSize(preset);state.pages=[makePage(width,height)];state.name=sample?'My member card':preset==='card'?'My card layout':'My document';$('#document-name').value=state.name;await showPage(0,{save:false});if(sample)createSampleCard();}
function createSampleCard(){const page=current(),w=page.width,h=page.height;const objects=[
  [new F.Rect({left:0,top:0,width:w,height:40,fill:'#7960d8',strokeWidth:0}),'Header band'],
  [new F.IText('PAPERLY CLUB',{left:14,top:13,fontFamily:'Arial',fontSize:11,fontWeight:'bold',fill:'#ffffff'}),'Club name'],
  [new F.IText('MEMBER CARD',{left:w-89,top:16,fontFamily:'Arial',fontSize:6.5,fill:'#ede4ff'}),'Card label'],
  [new F.Rect({left:15,top:53,width:57,height:70,fill:'#eee8f6',strokeWidth:0,rx:4,ry:4}),'Photo background'],
  [new F.Circle({left:33,top:64,radius:10,fill:'#c6b5dc',strokeWidth:0}),'Avatar head'],
  [new F.Ellipse({left:24,top:87,rx:19,ry:14,fill:'#c6b5dc',strokeWidth:0}),'Avatar shoulders'],
  [new F.IText('YOUR NAME',{left:85,top:55,fontFamily:'Arial',fontSize:15,fontWeight:'bold',fill:'#3d304a'}),'Member name'],
  [new F.IText('Creative community',{left:85,top:79,fontFamily:'Arial',fontSize:8,fill:'#9f8aaf'}),'Membership type'],
  [new F.IText('MEMBER NO.  001',{left:85,top:99,fontFamily:'Arial',fontSize:7.5,fill:'#7960a1'}),'Member number'],
  [new F.IText('Your ideas belong here.',{left:85,top:115,fontFamily:'Arial',fontSize:7.5,fill:'#a997b8'}),'Member tagline'],
  [new F.Line([15,h-18,w-15,h-18],{stroke:'#e6dcef',strokeWidth:.7}),'Footer line'],
  [new F.IText('SAMPLE COMMUNITY CARD · EDITABLE TEMPLATE',{left:15,top:h-13,fontFamily:'Arial',fontSize:4.8,fill:'#b5a1c5'}),'Template footer']
];for(const [object,label]of objects)canvas.add(configureObject(object,label));commit();canvas.requestRenderAll();updateSelection();}
$('#blank-a4').onclick=()=>blankDocument('a4');$('#blank-card').onclick=()=>blankDocument('card');$('#sample-card').onclick=()=>blankDocument('card',true);$('#add-page').onclick=async()=>{if(state.busy)return;saveScene();const [w,h]=presetSize($('#page-preset').value);state.pages.push(makePage(w,h));await showPage(state.pages.length-1,{save:false});state.dirty=true;};
$('#open-file').onclick=$('#empty-open').onclick=()=>{if(!state.busy)$('#document-file').click();};$('#document-file').onchange=async event=>{await openFile(event.target.files[0]);event.target.value='';};$('#document-name').oninput=()=>{state.name=$('#document-name').value.trim()||'Untitled document';};
$('#add-text').onclick=addText;$('#add-rectangle').onclick=()=>addRectangle(false);$('#add-cover').onclick=()=>addRectangle(true);document.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>setMode(button.dataset.mode));$('#select-existing').onclick=()=>setMode('existing');$('#zoom-fit').onclick=fitCanvas;$('#zoom-in').onclick=()=>setZoom(state.zoom*1.2);$('#zoom-out').onclick=()=>setZoom(state.zoom/1.2);
$('#add-image').onclick=()=>{if(!current()||state.busy)return;state.imageAction='add';$('#object-image').click();};$('#replace-image').onclick=()=>{state.imageAction='replace';$('#object-image').click();};
$('#object-image').onchange=async event=>{const file=event.target.files[0];if(!file||state.busy)return;const target=canvas.getActiveObject();try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('This image could not be read.'));reader.readAsDataURL(file);});if(state.imageAction==='replace'&&target instanceof F.FabricImage){const width=target.getScaledWidth(),height=target.getScaledHeight();await target.setSrc(data);target.set({scaleX:width/target.width,scaleY:height/target.height});target.setCoords();commit();updateSelection();canvas.requestRenderAll();}else{const image=await F.FabricImage.fromURL(data);const fit=Math.min(current().width*.3/image.width,current().height*.35/image.height);image.set({left:current().width*.12,top:current().height*.2,scaleX:fit,scaleY:fit});addObject(image,'Image: '+file.name);}notify('Image added. Drag its handles to fit it to your layout.');}catch(error){notify(error.message||'This image could not be opened.',true);}finally{event.target.value='';}};
async function loadTesseract(){if(window.Tesseract)return window.Tesseract;return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='../assets/engines/tesseract.min.js';script.onload=()=>resolve(window.Tesseract);script.onerror=()=>reject(new Error('The OCR engine could not load. Check your connection and retry.'));document.head.append(script);});}
async function detectScanText(){
  if(!current()||state.busy)return;const page=current();if(!page.background){notify('This blank page already has editable elements. Select any text to change it.');return;}
  const job=crypto.randomUUID();state.ocrJob=job;state.ocrCanceled=false;const cancellation=new Promise((_,reject)=>{state.cancelOcr=()=>reject(new DOMException('Recognition canceled.','AbortError'));});progress('Finding words on your page…','English recognition runs on this device. The model downloads on first use.');$('#cancel-ocr').hidden=false;
  try{const Tesseract=await Promise.race([loadTesseract(),cancellation]);const initializing=Tesseract.createWorker('eng',1,{logger:message=>{if(state.ocrJob===job&&!state.ocrCanceled&&message.status==='recognizing text'){progress('Finding words on your page…',`${Math.round(message.progress*100)}% recognized`,message.progress);$('#cancel-ocr').hidden=false;}}});initializing.then(worker=>{if(state.ocrJob!==job)worker.terminate().catch(()=>{});}).catch(()=>{});const worker=await Promise.race([initializing,cancellation]);state.ocr=worker;const {data}=await Promise.race([worker.recognize(page.background,{}, {blocks:true,text:true}),cancellation]);if(state.ocrCanceled)return;const image=new Image();image.src=page.background;await image.decode();const sx=page.width/image.naturalWidth,sy=page.height/image.naturalHeight;const lines=(data.blocks||[]).flatMap(block=>(block.paragraphs||[]).flatMap(paragraph=>paragraph.lines||[]));const regions=lines.filter(line=>line.text?.trim()&&line.bbox).map(line=>({id:crypto.randomUUID(),text:line.text.trim(),x:line.bbox.x0*sx,y:line.bbox.y0*sy,width:(line.bbox.x1-line.bbox.x0)*sx,height:(line.bbox.y1-line.bbox.y0)*sy,fontSize:Math.max(2,(line.bbox.y1-line.bbox.y0)*sy/1.05),fontFamily:'Arial',origin:'OCR'}));page.detected=regions;setMode('existing');notify(regions.length?`${regions.length} text regions found. Click one to edit; review recognition and font matching.`:'No text regions found. Try a clearer scan, or use Cover area + Add text.',!regions.length);}
  catch(error){if(!state.ocrCanceled)notify(error.message||'Recognition failed. Try a clearer scan.',true);}
  finally{state.ocrJob=null;state.cancelOcr=null;if(state.ocr){await state.ocr.terminate().catch(()=>{});state.ocr=null;}done();}
}
$('#ocr-page').onclick=detectScanText;$('#cancel-ocr').onclick=()=>{state.ocrCanceled=true;state.cancelOcr?.();$('#progress-detail').textContent='Recognition canceled.';};
async function flattenedCanvas(page,scale){await preparePage(page);const output=new F.StaticCanvas(null,{width:Math.ceil(page.width*scale),height:Math.ceil(page.height*scale),enableRetinaScaling:false,backgroundColor:'#ffffff'});try{await output.loadFromJSON(page.scene);output.backgroundColor='#ffffff';output.backgroundImage=await backgroundImage(page);output.setViewportTransform([scale,0,0,scale,0,0]);output.renderAll();return output.toCanvasElement(1);}finally{await output.dispose();}}
function asBlob(element,type='image/png',quality=.95){return new Promise((resolve,reject)=>element.toBlob(blob=>blob?resolve(blob):reject(new Error('This page exceeds your browser’s image export capacity. Choose a lower resolution.')),type,quality));}
function download(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('#export-editor').onclick=()=>{if(!current()||state.busy)return;canvas.getActiveObject()?.exitEditing?.();clearTimeout(propertyTimer);commit();saveScene();$('#export-name').value=state.name||'my-edited-document';$('#export-dialog').showModal();};
$('#download-document').onclick=async()=>{
  if(state.busy||!current())return;$('#export-dialog').close();canvas.getActiveObject()?.exitEditing?.();commit();saveScene();const format=$('#export-format').value,scale=Number($('#export-resolution').value)||2;const name=($('#export-name').value.trim().replace(/\.(pdf|png|jpe?g)$/i,'').replace(/[<>:"/\\|?*\x00-\x1f]/g,'-')||'my-edited-document').slice(0,120);progress('Putting your document together…');
  try{if(format==='pdf'){const doc=await PDFLib.PDFDocument.create();doc.setTitle(name);doc.setCreator('Paperly Document Studio');for(let i=0;i<state.pages.length;i++){progress(`Finishing page ${i+1} of ${state.pages.length}…`,'Creating flattened pages with your visible changes.',i/state.pages.length);const page=state.pages[i],raster=await flattenedCanvas(page,scale);const image=await doc.embedPng(await (await asBlob(raster)).arrayBuffer());doc.addPage([page.width,page.height]).drawImage(image,{x:0,y:0,width:page.width,height:page.height});raster.width=raster.height=0;}download(new Blob([await doc.save()],{type:'application/pdf'}),name+'.pdf');}else{const raster=await flattenedCanvas(current(),scale);download(await asBlob(raster,format==='jpeg'?'image/jpeg':'image/png'),name+(format==='jpeg'?'.jpg':'.png'));raster.width=raster.height=0;}state.dirty=false;$('#save-status').textContent='Export downloaded · edits remain in this tab';notify('Your edited document is ready. Download complete.');}catch(error){notify(error.message||'Export failed. Try a lower resolution.',true);}finally{done();}
};
$('#help-editor').onclick=()=>$('#editor-guide').showModal();document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>button.closest('dialog').close());
window.addEventListener('keydown',event=>{if(state.busy||!current()||document.querySelector('dialog[open]'))return;const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||canvas.getActiveObject()?.isEditing;if(typing)return;const meta=event.ctrlKey||event.metaKey;if(meta&&event.key.toLowerCase()==='z'){event.preventDefault();undoRedo(event.shiftKey?1:-1);return;}if(meta&&event.key.toLowerCase()==='y'){event.preventDefault();undoRedo(1);return;}if(meta&&event.key.toLowerCase()==='d'){event.preventDefault();duplicateSelected();return;}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();removeSelected();return;}if(event.key==='Escape'){canvas.discardActiveObject();setMode('select');updateSelection();return;}const shifts={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(shifts[event.key]){const object=canvas.getActiveObject();if(!object)return;event.preventDefault();const factor=event.shiftKey?10:1;object.set({left:object.left+shifts[event.key][0]*factor,top:object.top+shifts[event.key][1]*factor});object.setCoords();canvas.requestRenderAll();commit();updateSelection();}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(current()&&!state.busy)fitCanvas();},180);});window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('dragover',event=>{if(Array.from(event.dataTransfer.types).includes('Files'))event.preventDefault();});window.addEventListener('drop',event=>{if(!event.dataTransfer.files.length)return;event.preventDefault();openFile(event.dataTransfer.files[0]);});
updateButtons();
for(const id of ['open-file','empty-open','sample-card','blank-a4','blank-card','help-editor'])$('#'+id).disabled=false;
document.documentElement.dataset.editorReady='true';
